package io.github.diodeme.ji.extension;

/** Side-effect contract used to decide whether an interrupted Tool attempt may continue. */
public enum ToolRetryContract {
    READ_ONLY,
    IDEMPOTENT,
    RESUMABLE,
    NON_RETRYABLE;

    public boolean mayResume(String durableResumeToken) {
        return this == READ_ONLY || this == IDEMPOTENT
                || this == RESUMABLE && durableResumeToken != null && !durableResumeToken.isBlank();
    }

    public static ToolRetryContract failClosed(ToolRetryContract value) {
        return value == null ? NON_RETRYABLE : value;
    }
}
